package com.nextrade.domain.ledger; import com.nextrade.common.enumtype.LedgerEntryType; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; public record Fee(LedgerEntry entry) { public Fee { if(entry.type()!=LedgerEntryType.FEE) throw new IllegalArgumentException("Wrong ledger type"); } public static Fee of(UserId user,Money amount,String reference){ return new Fee(new LedgerEntry(LedgerEntryId.generate(),user,LedgerEntryType.FEE,amount,reference,java.time.Instant.now())); } }